import { ChevronLeftIcon, ChevronRightIcon } from "@chakra-ui/icons";
import {
  Box,
  Flex,
  Icon,
  IconButton,
  Modal,
  ModalBody,
  ModalCloseButton,
  ModalContent,
  ModalFooter,
  ModalOverlay,
  Spinner,
  VStack,
  useBreakpointValue,
  useColorMode,
} from "@chakra-ui/react";
import React, { useEffect, useState } from "react";
import MediaType from "./MediaType";
import SmallMediaType from "./SmallMediaType";

export interface Media {
  id: string;
  type?: string;
  url?: string;
  element?: React.ReactNode;
  smallElement?: React.ReactNode;
}

interface GalleryProps {
  isOpen: boolean;
  onClose: () => void;
  startIndex?: number;
  setStartIndex?: (index: number) => void;
  media: Media[];
  navigationOrientation?: "horizontal" | "vertical";
}

const Gallery = ({
  isOpen,
  onClose,
  media,
  startIndex = 0,
  setStartIndex = () => {},
  navigationOrientation = "horizontal",
}: GalleryProps) => {
  const isBaseSize = useBreakpointValue(
    { base: true, md: false },
    { ssr: false }
  );

  return (
    <Modal isOpen={isOpen} onClose={onClose} size="full">
      <ModalOverlay bgColor="blackAlpha.800" />
      <ModalContent
        bg="transparent"
        display="flex"
        onKeyDown={(e) => {
          if (
            (e.key === "ArrowLeft" || e.key === "ArrowUp") &&
            startIndex > 0
          ) {
            setStartIndex(startIndex - 1);
          }
          if (
            (e.key === "ArrowRight" || e.key === "ArrowDown") &&
            startIndex < media.length - 1
          ) {
            setStartIndex(startIndex + 1);
          }
        }}
      >
        <ModalCloseButton
          bg="whiteAlpha.600"
          variant="solid"
          colorScheme="whiteAlpha"
          size="lg"
          zIndex={99999}
        />
        <ModalBody
          flexGrow={2}
          flexShrink={0}
          flexBasis="1px"
          display="flex"
          alignItems="start"
          gridGap={4}
          justifyContent="center"
          overflowX="hidden"
          p={0}
        >
          {!isBaseSize && navigationOrientation === "vertical" ? (
            <VStack
              bgColor="blackAlpha.600"
              alignItems="center"
              justifyContent="center"
              minWidth="10rem"
              overflowY="auto"
              height="100%"
              spacing={4}
            >
              {media.map((item, index) => (
                <Box
                  flexShrink={0}
                  borderRadius="lg"
                  key={item.id}
                  p={0}
                  _hover={{
                    cursor: "pointer",
                  }}
                  onClick={() => {
                    setStartIndex(index);
                  }}
                >
                  {item.smallElement || (
                    <SmallMediaType
                      url={item.url!}
                      type={item.type!}
                      id={item.id!}
                      index={index}
                      startIndex={startIndex}
                    />
                  )}
                </Box>
              ))}
            </VStack>
          ) : null}
          <Flex
            height="100%"
            width="100%"
            py={8}
            alignItems="center"
            justifyContent="space-between"
            position="relative"
          >
            <IconButton
              isDisabled={startIndex === 0}
              aria-label="previous"
              variant="unstyled"
              display="flex"
              alignItems="center"
              justifyContent="center"
              bg={isBaseSize ? "gray.100" : "whiteAlpha.600"}
              color={isBaseSize ? "gray.900" : "white"}
              ml={isBaseSize ? "0.25rem" : "1rem"}
              {...(isBaseSize
                ? {
                    position: "absolute",
                    left: 0,
                  }
                : {})}
              size="lg"
              onClick={() => {
                if (startIndex > 0) {
                  setStartIndex(startIndex - 1);
                }
              }}
              icon={
                <Icon as={ChevronLeftIcon} width="1.5rem" height="1.5rem" />
              }
            />
            <Box mx="auto">
              {media[startIndex]?.element || (
                <MediaType
                  url={media[startIndex]?.url!}
                  type={media[startIndex]?.type!}
                  id={media[startIndex]?.id!}
                />
              )}
            </Box>
            <IconButton
              aria-label="next"
              variant="unstyled"
              display="flex"
              alignItems="center"
              justifyContent="center"
              isDisabled={startIndex === media.length - 1}
              bg={isBaseSize ? "gray.100" : "whiteAlpha.600"}
              color={isBaseSize ? "gray.900" : "white"}
              onClick={() => {
                if (startIndex < media.length - 1) {
                  setStartIndex(startIndex + 1);
                }
              }}
              mr={isBaseSize ? "0.25rem" : "1rem"}
              {...(isBaseSize
                ? {
                    position: "absolute",
                    right: 0,
                  }
                : {})}
              size="lg"
              icon={
                <Icon as={ChevronRightIcon} width="1.5rem" height="1.5rem" />
              }
            />
          </Flex>
        </ModalBody>
        {!isBaseSize && navigationOrientation === "horizontal" ? (
          <ModalFooter
            flexGrow={1}
            flexShrink={0}
            flexBasis="1px"
            bgColor="blackAlpha.600"
            alignItems="center"
            justifyContent="start"
            flexWrap="nowrap"
            overflowX="auto"
            gridGap={4}
            maxHeight="15rem"
            w="100%"
          >
            {media.map((item, index) => (
              <Box
                flexShrink={0}
                borderRadius="lg"
                key={item.id}
                p={0}
                _hover={{
                  cursor: "pointer",
                }}
                onClick={() => {
                  setStartIndex(index);
                }}
              >
                {item.smallElement || (
                  <SmallMediaType
                    url={item.url!}
                    type={item.type!}
                    id={item.id!}
                    index={index}
                    startIndex={startIndex}
                  />
                )}
              </Box>
            ))}
          </ModalFooter>
        ) : null}
      </ModalContent>
    </Modal>
  );
};

export default Gallery;
