import { Button, Link, Text, useBreakpointValue, Icon, useClipboard } from "@chakra-ui/react";
import { CheckIcon, CopyIcon, PhoneIcon }  from "@chakra-ui/icons";
import React from "react";
import { useTranslation } from "react-i18next";

const CallButton = () => {
    const { t } = useTranslation();
    const { onCopy, value, setValue, hasCopied } = useClipboard('+372 5656 6936');
    const isBaseSize = useBreakpointValue(
        { base: true, md: false },
        { ssr: false }
    );

    return isBaseSize ? (
        <Link
            href="tel:+37256566936"
            _hover={{
                textDecoration: "none",
            }}
        >
            <Button
                size={isBaseSize ? "sm" : "lg"}
                colorScheme="green"
                display="flex"
                gridGap={2}
                alignItems="center"
                borderRadius="full"
                leftIcon={<Icon as={PhoneIcon} />}
            >
                <Text>{t("callUs")}</Text>
            </Button>
        </Link>
    ) : (
        <Button
            size={isBaseSize ? "sm" : "lg"}
            colorScheme="green"
            display="flex"
            gridGap={2}
            alignItems="center"
            borderRadius="full"
            onClick={onCopy}
            leftIcon={<Icon as={PhoneIcon} />}
            rightIcon={<Icon as={hasCopied ? CheckIcon : CopyIcon} />}
        >
            <Text>{value}</Text>
        </Button>
    );
};

export default CallButton;