import { AspectRatio, Image, useColorMode } from "@chakra-ui/react";
import React from "react";

interface SmallMediaTypeProps {
  type: string;
  url: string;
  id: string;
  index: number;
  startIndex: number;
}

const SUPPORTED_MEDIA_TYPES = [
  "image/jpeg",
  "image/jpg",
  "image/png",
  "video/mp4",
  "image/gif",
];

const SmallMediaType = ({
  type,
  url,
  id,
  index,
  startIndex,
}: SmallMediaTypeProps) => {
  const { colorMode } = useColorMode();

  return (
    <>
      {type.includes("image") && SUPPORTED_MEDIA_TYPES.includes(type) && (
        <Image
          src={url}
          alt={`item-${id}`}
          boxSize="100%"
          objectFit="cover"
          borderRadius="lg"
          {...(index === startIndex
            ? {
                borderWidth: "3px",
                borderStyle: "solid",
                borderColor:
                  colorMode === "dark"
                    ? "blue.200"
                    : "blue.600",
              }
            : {})}
          width="10rem"
          height="10rem"
        />
      )}
      {type.includes("video") && SUPPORTED_MEDIA_TYPES.includes(type) && (
        <AspectRatio
          borderRadius="lg"
          maxWidth="10rem"
          width="10rem"
          height="10rem"
          maxHeight="10rem"
          {...(index === startIndex
            ? {
                borderWidth: "3px",
                borderStyle: "solid",
                borderColor:
                  colorMode === "dark"
                    ? "blue.200"
                    : "blue.600",
              }
            : {})}
        >
          <video
            controls
            style={{
              borderRadius: "0.5rem",
            }}
          >
            <source src={url} type={type} />
          </video>
        </AspectRatio>
      )}
    </>
  );
};

export default SmallMediaType;
